-- AoTT-8311 V3 bounded runtime state reader for community helper daemons.
-- Reads only root-owned RAM state generated by fixed AoTT scripts.
local fs=require "nixio.fs"
local M={}
local ROOT="/run/aott-runtime"
local SPECS={
    pingd={path=ROOT.."/pingd.state",script="/usr/sbin/8311-pingd.sh",target=true},
    rarpd={path=ROOT.."/rarpd.state",script="/usr/sbin/8311-rarpd.sh",target=false},
    rxlos={path=ROOT.."/rxlos.state",script="/usr/sbin/8311-rx_los.sh",target=false},
}

local function ipv4(value)
    if type(value)~="string" or #value>15 then return nil end
    local a,b,c,d=value:match("^(%d+)%.(%d+)%.(%d+)%.(%d+)$")
    if not a then return nil end
    for _,part in ipairs({a,b,c,d}) do
        if #part>3 or (#part>1 and part:sub(1,1)=="0") or tonumber(part)>255 then
            return nil
        end
    end
    return value
end

local function boot_id()
    local value=fs.readfile("/proc/sys/kernel/random/boot_id",80)
    if type(value)~="string" then return nil end
    value=value:gsub("[\r\n]+$","")
    if not value:match("^[0-9a-f]+%-[0-9a-f%-]+$") or #value>64 then return nil end
    return value
end

local function parse(data)
    if type(data)~="string" or #data>512 or data:find("[%z\1-\8\11\12\14-\31\127]") then
        return nil
    end
    local out={}
    for line in (data.."\n"):gmatch("(.-)\n") do
        if line~="" then
            local key,value=line:match("^([a-z_]+)=([^=\r\n]*)$")
            if not key or out[key]~=nil then return nil end
            out[key]=value
        end
    end
    return out
end

function M.read(name)
    local spec=SPECS[name]
    if not spec then return nil,"unknown_daemon_state" end
    local dir=fs.lstat(ROOT)
    if not dir or dir.type~="dir" or dir.uid~=0 or dir.modedec~=700 then
        return nil,"runtime_state_directory_unavailable"
    end
    local st=fs.lstat(spec.path)
    if not st or st.type~="reg" or st.uid~=0 or st.modedec~=600 or
       st.nlink~=1 or type(st.size)~="number" or st.size>512 then
        return nil,"runtime_state_file_unavailable"
    end
    local row=parse(fs.readfile(spec.path,513))
    if not row or row.schema~="1" then return nil,"runtime_state_invalid" end
    local pid=tonumber(row.pid)
    if not pid or pid<1 or pid~=math.floor(pid) then return nil,"runtime_pid_invalid" end
    if row.enabled~="0" and row.enabled~="1" then return nil,"runtime_enabled_invalid" end
    if row.active~="0" and row.active~="1" then return nil,"runtime_active_invalid" end
    local current_boot=boot_id()
    if not current_boot or row.boot_id~=current_boot then return nil,"runtime_boot_mismatch" end
    local cmd=fs.readfile("/proc/"..tostring(pid).."/cmdline",2048)
    if type(cmd)~="string" or not cmd:find(spec.script,1,true) then
        return nil,"runtime_process_identity_mismatch"
    end
    local target=nil
    if spec.target then
        target=ipv4(row.target)
        if not target then return nil,"runtime_target_invalid" end
    elseif row.target~=nil then
        return nil,"unexpected_runtime_target"
    end
    return {
        schema=1,name=name,pid=pid,enabled=row.enabled=="1",
        active=row.active=="1",target=target,boot_id=current_boot,
        process_identity_verified=true,
    }
end

M.root=ROOT
M.specs=SPECS
return M
